import {debriefPages,groupPages,renderGroupPage,measureProjection} from './presentation.js';
import {instructorEntry} from './instructor-entry.js';
import {attachDescriptionRecorder} from './description-recorder.js';
import { config } from './config.js';
import { makeDemo } from './demo.js';
import { renderDebriefSlide, exampleCards, linkGroups } from './debrief-view.js';
import { adminForm, joinForm, classInvitation, displayCode } from './admin-join.js';
import { joinLink, joinPresentation, qrSvg } from './join-presentation.js';
import { activitySetupForm, templateReviewForm, readTemplateReview } from './activity-builder.js';
import { modelName, modelOptions, activityStatus } from './model-choice.js';

const $ = (s, root=document) => root.querySelector(s);
const e = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fragment = new URLSearchParams(location.hash.slice(1));
const state = {key:fragment.get('group') || fragment.get('test') || sessionStorage.getItem('sidecar-instructor') || localStorage.getItem('sidecar-instructor') || '',student:fragment.has('group'),tester:fragment.has('test'),second:fragment.get('view')==='debrief',sessionId:fragment.get('session'),data:null,selected:null,debriefIndex:0,demo:fragment.has('demo'),focusBlock:null,saving:new Set(),drafts:new Map(),conflicts:new Map(),connectionLost:false,polling:false,viewEpoch:0,aiBusy:false,lastAuto:0,present:null,projection:null,joinProjection:null};
state.sandbox=state.key.startsWith('w_');
state.account=state.key.startsWith('u_');
let toastTimer, modalReturnFocus, activityDraft, disposeRecorder;
function toast(message) {const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),6500);}
function icon(name){const paths={lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 13v7h14v-7"/>',screen:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',play:'<path d="m8 4 12 8-12 8Z"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};return `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||''}</svg>`;}
async function api(action, payload={}) {
  if(state.demo) return demoApi(action,payload);
  if(!config.endpoint) throw new Error('The database connection is still being configured. Try the demo in the meantime.');
  const r = await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'application/json','x-classroom-key':state.key},body:JSON.stringify({action,...payload}),signal:AbortSignal.timeout(['debrief','admin_save','generate_template','create'].includes(action)?75000:20000)});
  let data;try{data=await r.json();}catch{throw new Error('The server did not respond. Check your connection and retry.');}
  if(!r.ok){const error=new Error(data.error||'Request failed.');error.status=r.status;throw error;} return data;
}
function demoApi(action,p) {
  const d=state.data;
  if(action==='get')return structuredClone(d);
  if(action==='save_block'){const b=d.blocks.find(b=>b.id===p.id);Object.assign(b,p,{revision:b.revision+1});return {block:structuredClone(b)};}
  if(action==='save_slide'){const s=d.slides.find(s=>s.id===p.id);Object.assign(s,p,{revision:s.revision+1});return {slide:structuredClone(s)};}
  if(action==='add_block'){const b={id:crypto.randomUUID(),slide_id:p.slideId,label:'New text box',content:'',style:{},position:d.blocks.length,revision:0};d.blocks.push(b);return {block:b};}
  if(action==='add_slide'){const id=crypto.randomUUID();const s={id,group_id:p.groupId,session_id:'demo',title:p.title||'Our next idea',theme:'paper',position:d.slides.length,revision:0};d.slides.push(s);const original=d.blocks.filter(b=>b.slide_id===p.duplicateId);d.blocks.push(...(original.length?original:[{label:'Our idea',content:'',style:{},position:0}]).map(b=>({...b,id:crypto.randomUUID(),slide_id:id,revision:0})));return {id};}
  if(action==='delete_slide'){if(d.slides.filter(s=>s.group_id===d.slides.find(s=>s.id===p.id)?.group_id).length<=1)throw new Error('Keep at least one slide per group.');d.slides=d.slides.filter(s=>s.id!==p.id);d.blocks=d.blocks.filter(b=>b.slide_id!==p.id);return {};}
  if(action==='delete_block'){d.blocks=d.blocks.filter(b=>b.id!==p.id);return {};}
  if(action==='settings'){Object.assign(d.session,{...p,debrief_prompt:p.prompt??d.session.debrief_prompt,auto_debrief:p.auto??d.session.auto_debrief,slide_count:p.slideCount??d.session.slide_count});if(p.status==='live')d.session.ends_at=new Date(Date.now()+p.minutes*60000).toISOString();return {};}
  if(action==='debrief')return {skipped:'This is a sample debrief. Connect as instructor to generate real AI updates.'};
  if(action==='history')return {history:[{content:d.session.debrief,created_at:d.session.debrief_at}]};
  throw new Error('This action is available in your connected classroom.');
}
function brand(){return `<div class="brand"><img src="icon.svg" alt=""><span>sidecar</span><span class="label">A little ahead of the room.</span></div>`;}
function sandboxBanner(){return state.sandbox?'<div class="demo-banner">Test instructor workspace · Try the sample or create an activity. AI is connected.</div>':'';}
function topbar(actions=''){return `<header class="topbar">${brand()}<div class="top-actions">${actions}</div></header>`;}
function setUrl(){if(state.student)return;const params=new URLSearchParams();if(state.demo)params.set('demo','1');else if(state.tester)params.set('test',state.key);else if(state.sessionId)params.set('session',state.sessionId);if(state.second)params.set('view','debrief');history.replaceState(null,'',location.pathname+(params.size?'#'+params:''));}
function showLogin(error='',signup=false,email='') {
  state.viewEpoch++;state.data=null;$('#app').className='';
  $('#app').innerHTML=instructorEntry({brand:brand(),error,signup,email});
}
async function dashboard() {
  const epoch=++state.viewEpoch;
  state.data=null;state.sessionId=null;state.second=false;setUrl();
  $('#app').innerHTML=sandboxBanner()+topbar(`${!state.sandbox&&!state.account?'<button data-action="admin" class="quiet">AI settings</button>':''}<button data-action="logout" class="quiet">Sign out</button>`)+`<main class="dashboard"><div class="row spread"><div><div class="eyebrow">${state.sandbox?'A space to try things':'Your teaching workspace'}</div><h1>Your activities.</h1></div><button class="primary" data-action="create">＋ New activity</button></div><p class="dashboard-intro">${state.sandbox?'Open the sample, try a few edits, and see the debrief take shape.':'A place for every idea. A clear next step for your class.'}</p><div class="dashboard-steps" aria-label="Classroom workflow"><span><b>1</b> Describe the project</span><span><b>2</b> Invite & start</span><span><b>3</b> Lead the debrief</span></div><div class="dashboard-section-heading"><h2>${state.sandbox?'Your sample activities':'Ready when you are'}</h2><span>Private instructor workspace</span></div><div class="session-grid" id="session-list"><p class="muted">Loading your activities…</p></div></main>`;
  try{const {sessions}=await api('list');if(epoch!==state.viewEpoch||!$('#session-list'))return;$('#session-list').innerHTML=sessions.length?sessions.map(s=>`<article class="session-card"><button class="session-open" data-action="open-session" data-id="${e(s.id)}"><span class="pill">${e(activityStatus(s))}</span><h3>${e(s.title)}</h3><p class="activity-meta">${s.work_mode==='individual'?'Individual work':'Group work'}</p><small>${new Date(s.created_at).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})} &nbsp; · &nbsp; Open activity →</small></button><button class="quiet activity-delete" data-action="delete-session" data-id="${e(s.id)}" data-title="${e(s.title)}" title="Delete activity" aria-label="Delete ${e(s.title)}"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/></svg></button></article>`).join(''):`<div class="session-card"><span class="eyebrow">Start here</span><h3>What will your class explore?</h3><p>Describe your project. We’ll turn it into a slide template you can make your own.</p><button data-action="create" class="primary">Create your first activity</button></div>`;}catch(error){if(epoch===state.viewEpoch)showLogin(error.message);}
}
async function openSession(id) {state.viewEpoch++;state.sessionId=id;state.selected=null;await refresh(true);setUrl();}
async function refresh(full=false) {
  if(state.polling&&!full)return;const request={epoch:state.viewEpoch};state.polling=request;
  try {
    const data=await api('get',{sessionId:state.sessionId});if(request.epoch!==state.viewEpoch||state.polling!==request)return;state.connectionLost=false;state.data=data;state.sessionId=data.session.id;
    if(!data.slides.some(s=>s.id===state.selected))state.selected=data.slides[0]?.id;
    if(full || !$('#workspace')) renderWorkspace(); else {
      if($('#sidebar'))$('#sidebar').innerHTML=sidebar();
      const signature=JSON.stringify({s:data.session,busy:state.aiBusy});
      if($('#right')&&signature!==state.rightSignature){$('#right').innerHTML=debriefPanel();state.rightSignature=signature;}
      const typing=document.activeElement?.matches('[data-field]');
      if(typing)syncOtherBlocks();
      if(!typing && !state.drafts.size && !state.conflicts.size && $('#canvas'))$('#canvas').innerHTML=canvas();
      if($('#editor-status'))$('#editor-status').textContent=saveStatus();
      updateClock();updateStudentState();
      if(state.projection)updateProjectionNotice();
      if(state.joinProjection)paintJoinPresentation();
    }
  }catch(error){if(request.epoch!==state.viewEpoch||state.polling!==request)return;if(full){showLogin(error.message);}else{state.connectionLost=true;updateClock();updateStudentState();const status=$('#editor-status');if(status)status.textContent=saveStatus();}}finally{if(state.polling===request)state.polling=false;}
}
function selectedSlide(){return state.data.slides.find(s=>s.id===state.selected)||state.data.slides[0];}
function writingOpen(){return ['draft','live'].includes(state.data.session.status);}
function editable(){return !state.student||writingOpen();}
function saveStatus(){if(state.connectionLost)return state.drafts.size?'Connection lost · draft kept in this tab':'Connection lost · reconnecting';return state.conflicts.size?'Review a conflicting edit':state.student&&state.drafts.size&&!editable()?'Draft kept · editing paused':state.drafts.size||state.saving.size?'Saving…':'All changes saved';}
function renderWorkspace() {
  const s=state.data.session;
  $('#app').className=[state.student?'student':'',state.second?'second-screen':''].join(' ');
  $('#app').innerHTML=sandboxBanner()+(state.tester?'<div class="demo-banner">Isolated test classroom · edit a group slide, start the timer, then try Present debrief. Sample names are fictional. Test access lasts 7 days, with up to 30 AI updates.</div>':'')+(state.demo?`<div class="demo-banner">Sample classroom · illustrative responses and debrief · no AI calls <button data-action="exit-demo">Use my workspace →</button></div>`:'')+topbar(state.student?`<span class="pill">${e(state.data.groups[0]?.name)} workspace</span><button data-action="copy-return" class="quiet">Save my link</button><button data-action="leave-class" class="quiet">← Back</button>`:`${state.tester?'<span class="pill">Test instructor</span>':`<button class="quiet" data-action="home">← My activities</button>`}<button class="quiet secondary-action" data-action="export">Export</button><button data-action="share">${icon('share')} Invite class</button><div class="avatar" title="Instructor">IN</div>`)+`<section class="sessionbar"><div><div class="eyebrow">${state.student?(s.work_mode==='individual'?'Individual activity':'Group activity'):'Instructor workspace'} &nbsp; / &nbsp; <span id="session-status">${e(activityStatus(s))}</span></div><h1>${e(s.title)}</h1></div><div class="row"><span class="pill" id="editing-badge">${writingOpen()?'<span class="dot"></span> '+(state.student?'Editing open':'Students can write'):'Writing paused'}</span><div class="timer">${!state.student?`<button class="quiet" data-action="toggle-writing">${writingOpen()?'Pause writing':'Open writing'}</button>`:''}${icon('clock')}<span class="clock" id="clock">08:00</span>${!state.student?`<button class="primary" data-action="timer" id="timer-button">${s.status==='live'?'Pause activity':'Start timer & AI'}</button><button class="quiet icon" data-action="activity-settings" aria-label="Activity settings">⚙</button>`:''}</div></div></section><div class="workspace" id="workspace">${!state.second?`<aside class="sidebar" id="sidebar">${sidebar()}</aside><main class="main-editor"><div class="editor-heading"><div class="row"><strong>${state.student?e(s.work_mode==='individual'?'Your slides':state.data.groups[0]?.name+' · Your slides'):(s.work_mode==='individual'?'Individual slides':'Group slides')}</strong>${!state.student?`<span class="pill">${state.data.groups.length} ${s.work_mode==='individual'?'students':'groups'}</span>`:''}</div><span class="saved" id="editor-status">${saveStatus()}</span></div>${state.student?studentTask():''}<div class="toolbar">${toolbar()}</div><div class="canvas-wrap" id="canvas">${canvas()}</div>${!state.student?`<details class="activity-note"><summary>The activity brief</summary><p>${e(s.instructions)}</p></details>`:''}</main>`:''}${!state.student?`<aside class="debrief-panel" id="right">${debriefPanel()}</aside>`:''}</div>`;
  updateClock();updateStudentState();
}
function sidebar(){return `<div class="sidebar-title"><span class="eyebrow">${state.student?'Your deck':'The room'}</span><span class="eyebrow">${state.data.slides.length}</span></div>${!state.student?roomSummary():''}`+state.data.groups.map((g,i)=>`<div class="group-section"><div class="group-label"><span class="group-dot" style="background:${['#829774','#b68d72','#7f97ab','#a095b1'][i%4]}"></span>${e(g.name)}</div>${!state.student?`<div class="group-progress">${groupProgress(g.id)}</div>`:''}${state.data.slides.filter(s=>s.group_id===g.id).map((s,j)=>`<button class="thumb ${s.id===state.selected?'selected':''}" data-action="select-slide" data-id="${e(s.id)}" aria-label="${e(s.title)}" aria-current="${s.id===state.selected}"><h4>${e(s.title)}</h4><div class="thumb-lines"></div><div class="thumb-lines short"></div><span class="thumb-number">${String(j+1).padStart(2,'0')}</span></button>`).join('')}</div>`).join('')+(editable()?`<button class="quiet" data-action="add-slide" style="width:100%;font-size:10px">＋ Add slide</button>`:'');}
function toolbar(){return `${editable()?`<button data-action="add-block">＋ Text box</button><button data-action="student-tools" aria-expanded="${Boolean(state.studentTools)}" aria-controls="slide-tools">Slide tools ${state.studentTools?'−':'+'}</button><div id="slide-tools" class="slide-tools" ${!state.studentTools?'hidden':''}><button data-action="format" data-format="bold" title="Bold selected text box"><b>B</b></button><button data-action="format" data-format="italic" title="Italic selected text box"><i>I</i></button><select id="font-size" aria-label="Text size"><option value="16">16 px</option><option value="20">20 px</option><option value="24">24 px</option><option value="28">28 px</option><option value="32">32 px</option></select><button data-action="format" data-format="align" title="Center selected text box">☰</button><input type="color" id="text-color" title="Text color" aria-label="Text color" value="#213d39"><span class="divider"></span><select id="theme" aria-label="Slide theme"><option value="paper">Paper</option><option value="sage">Sage</option><option value="midnight">Midnight</option></select><button data-action="duplicate" title="Duplicate current slide">Duplicate</button><button data-action="delete-slide" class="quiet" title="Delete current slide">⌫</button></div>`:`<span class="muted" style="font-size:11px">${state.data.session.status==='draft'?'Editing opens when your instructor starts.':`Writing is paused. ${state.drafts.size?'Your draft is kept in this tab.':'Your saved work is ready for discussion.'}`}</span>`}<button class="quiet" data-action="present" style="margin-left:auto">${icon('play')} Present</button>`;}
function blockHtml(b,readOnly=false){const s=b.style||{};return `<div class="block" data-block="${e(b.id)}" data-revision="${b.revision}"><textarea class="block-label" data-field="label" data-id="${e(b.id)}" maxlength="160" rows="${Math.max(1,Math.ceil(b.label.length/32))}" aria-label="Text box heading" ${readOnly?'readonly':''}>${e(b.label)}</textarea><div class="block-text" data-field="content" data-id="${e(b.id)}" contenteditable="${!readOnly}" role="textbox" aria-multiline="true" aria-label="${e(b.label||'Slide text')}" data-placeholder="Click here and add your thinking…" style="font-weight:${s.bold?700:400};font-style:${s.italic?'italic':'normal'};text-align:${e(s.align||'left')};${s.size?'font-size:'+Number(s.size)+'px;':''}${s.color?'color:'+e(s.color)+';':''}">${e(b.content)}</div><div class="contributor-row">${readOnly?(b.contributor?`<span>${e(b.contributor)}</span>`:''):`<label>Contributors <input data-field="contributor" data-id="${e(b.id)}" maxlength="120" placeholder="Names (optional)" value="${e(b.contributor||'')}" aria-label="Contributor names for ${e(b.label)}"></label>`}</div>${!readOnly?`<button class="block-delete danger" data-action="delete-block" data-id="${e(b.id)}" aria-label="Delete text box">×</button>`:''}</div>`;}
function slideHtml(slide,readOnly=false){const group=state.data.groups.find(g=>g.id===slide.group_id);return `<article class="slide-paper ${e(slide.theme)}"><div class="eyebrow">${e(group?.name)} &nbsp; / &nbsp; ${state.data.session.work_mode==='individual'?'Your reflection':'Think together'}</div><input class="slide-title" data-field="title" data-id="${e(slide.id)}" data-revision="${slide.revision}" maxlength="160" value="${e(slide.title)}" aria-label="Slide title" ${readOnly?'readonly':''}>${state.data.blocks.filter(b=>b.slide_id===slide.id).map(b=>blockHtml(b,readOnly)).join('')}<footer class="slide-foot"><span>${e(state.data.session.title.slice(0,65))}</span><span>sidecar</span></footer></article>`;}
function canvas(){const s=selectedSlide();if(!s)return '<div class="empty">No slides yet.</div>';return conflictsHtml()+slideHtml(s,!editable())+`<div class="canvas-caption"><span>${state.student?(state.data.session.work_mode==='individual'?'Your individual deck · keep your return link private.':'Your group shares these slides · use separate text boxes to write together.'):'Watch the room, or click a text box to help.'}</span><span>${state.demo?'Sample content':'Autosaves · syncs every 3 seconds'}</span></div>`;}
function debriefPanel(){const s=state.data.session;const slides=s.debrief?.slides||[];state.debriefIndex=Math.min(state.debriefIndex,Math.max(0,slides.length-1));const slide=slides[state.debriefIndex];return `<div class="panel-head"><h2>Your debrief</h2><span class="private-label">${icon('lock')} Only you</span></div><p class="panel-caption">A live reading of the room. You lead the conversation.${s.ai_model?`<span class="activity-model-caption">${e(modelName(s.ai_model))}</span>`:''}</p><div class="row spread"><span class="eyebrow">${e(s.focus.startsWith('Compare')?'Patterns & differences':s.focus.startsWith('Find')?'Misconceptions':s.focus.startsWith('Plan')?'Discussion plan':'Your focus')}</span><div class="debrief-controls"><button data-action="debrief-settings" class="quiet" title="Customize debrief">Customize</button><button data-action="popout" class="icon" title="Open private second screen" aria-label="Open private second screen">${icon('screen')}</button></div></div><div class="debrief-status"><span><span class="dot" style="background:${s.auto_debrief?'#77934a':'#a6aa9d'}"></span>${s.auto_debrief?'Auto · every 1 min':'Automatic updates paused'}</span><button class="quiet" style="padding:0;font-size:10px" data-action="auto">${s.auto_debrief?'Pause':'Enable'}</button></div><div class="debrief-live-line" id="debrief-live-line">${debriefStatus()}</div>${s.ai_error?`<p class="error-text">${e(s.ai_error)}</p>`:''}${slide?`<button class="project-debrief primary" data-action="project-debrief">${icon('screen')} Present debrief <span>↗</span></button><article class="debrief-card"><div class="eyebrow">Debrief ${String(state.debriefIndex+1).padStart(2,'0')} &nbsp; / &nbsp; ${String(slides.length).padStart(2,'0')}</div><h3>${linkGroups(slide.title,slide,state.data)}</h3><p class="takeaway">${linkGroups(slide.takeaway,slide,state.data)}</p><ul>${slide.bullets.map(b=>`<li>${linkGroups(b,slide,state.data)}</li>`).join('')}</ul>${slide.examples?.length?`<details class="preview-evidence"><summary>${slide.examples.length} attributed example${slide.examples.length===1?'':'s'} <span>View evidence ↓</span></summary>${exampleCards(slide.examples)}</details>`:''}<div class="question"><span>🎯 ASK THE ROOM</span>${linkGroups(slide.question,slide,state.data)}</div></article><div class="debrief-nav"><span>${s.debrief_at?'Updated '+new Date(s.debrief_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):''}</span><div class="dots">${slides.map((_,i)=>`<button class="${i===state.debriefIndex?'active':''}" data-action="debrief-page" data-index="${i}" aria-label="Debrief slide ${i+1}"></button>`).join('')}</div><div class="row" style="gap:1px"><button class="quiet icon" data-action="debrief-prev" aria-label="Previous debrief slide">‹</button><button class="quiet icon" data-action="debrief-next" aria-label="Next debrief slide">›</button></div></div><details class="notes"><summary>Your facilitation notes</summary><p>${e(slide.notes)}</p></details><div class="sources">${slide.sources.map(id=>{const source=state.data.slides.find(x=>x.id===id);const g=state.data.groups.find(g=>g.id===source?.group_id);return source?`<button class="source" data-action="source" data-id="${e(id)}">↗ ${e(g?.name)} · slide ${state.data.slides.filter(x=>x.group_id===source.group_id).findIndex(x=>x.id===id)+1}</button>`:'';}).join('')}</div>`:`<div class="debrief-card empty"><div class="empty-icon">${icon('spark')}</div><h3>First ideas, then insights.</h3><p>Your debrief draws on saved student writing. Leave automatic updates enabled during the activity, or choose Update now when you’re ready.</p></div>`}<div class="row spread" style="margin-top:20px"><button class="primary" data-action="generate" ${state.aiBusy?'disabled':''}>${icon('spark')} ${state.aiBusy?'Reading the room…':'Update now'}</button><button class="quiet" data-action="history" style="font-size:10px">History</button></div><p class="panel-bottom">${s.debrief?.total_workspaces?`Based on ${s.debrief.groups_with_content} of ${s.debrief.total_workspaces} workspaces with writing · ${e(s.debrief.model||'')}<br>`:''}${state.demo?'Illustrative debrief for this demo.':`${config.schedulerEnabled?'Updates run on the server while the activity is live.':'Keep this tab open for automatic updates.'} Unchanged work skips an AI call. OpenAI API usage is billed separately.`} AI drafts need your judgment. Group links never include this panel.</p>`;}
function updateClock(){if(!state.data)return;const s=state.data.session;let seconds=s.ends_at?Math.max(0,Math.ceil((new Date(s.ends_at)-Date.now())/1000)):0;const clock=$('#clock');if(clock)clock.textContent=s.status==='draft'?'Ready':s.status==='paused'?'Paused':s.status==='ended'?'Ended':`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if($('#session-status'))$('#session-status').textContent=activityStatus(s);if($('#timer-button'))$('#timer-button').textContent=s.status==='live'&&seconds>0?'Pause activity':'Start timer & AI';if($('[data-action=toggle-writing]'))$('[data-action=toggle-writing]').textContent=writingOpen()?'Pause writing':'Open writing';if($('#editing-badge'))$('#editing-badge').innerHTML=state.connectionLost?'Reconnecting…':writingOpen()?'<span class="dot"></span> '+(state.student?'Editing open':'Students can write'):'Writing paused';}
function modal(html){disposeRecorder?.();disposeRecorder=null;modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;setTimeout(()=>$('.modal input,.modal button,.modal select')?.focus(),0);}
function closeModal(){disposeRecorder?.();disposeRecorder=null;$('#modal-root').innerHTML='';modalReturnFocus?.focus();}
const focusOptions=['Compare ideas and surface productive disagreements','Find misconceptions and missing reasoning','Plan a Socratic discussion','Connect the activity to a learning objective'];
function options(value){return focusOptions.map(x=>`<option ${x===value?'selected':''}>${e(x)}</option>`).join('');}
function setupForm(values={}){modal(activitySetupForm(values,focusOptions));disposeRecorder=attachDescriptionRecorder($('#create-form'),transcribeDescription);loadActivityModels(values.model);}
async function transcribeDescription(recording,signal){
  const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),65000);
  const cancel=()=>abort.abort();signal.addEventListener('abort',cancel,{once:true});
  try{const url=new URL(config.endpoint);url.searchParams.set('action','transcribe_description');const response=await fetch(url,{method:'POST',headers:{'Content-Type':recording.type,'x-classroom-key':state.key},body:recording,signal:abort.signal});const result=await response.json();if(!response.ok)throw new Error(result.error||'Transcription failed. Retry or type your description.');return result;}
  catch(error){if(error.name==='AbortError')throw new Error('Transcription timed out. Retry or type your description.');throw error;}
  finally{clearTimeout(timeout);signal.removeEventListener('abort',cancel);}
}
async function loadActivityModels(selected) {
  const form=$('#create-form');if(!form)return;
  const picker=$('#activity-model',form),help=$('#activity-model-help',form),submit=$('button[type=submit]',form),reload=$('[data-action="reload-activity-models"]',form);
  const previous=selected||picker.value;form.dataset.modelsLoading='true';picker.disabled=true;submit.disabled=true;reload.disabled=true;
  try{const result=await api('activity_models');if(!form.isConnected)return;if(!result.models?.length)throw new Error('No available classroom models were returned.');const missing=previous&&!result.models.includes(previous),chosen=previous||(result.models.includes(result.defaultModel)?result.defaultModel:result.models[0]);picker.innerHTML=modelOptions(missing?[previous,...result.models]:result.models,chosen,result.defaultModel);help.textContent=missing?'Your selected model is not listed now. Choose another model or retry; it has not been changed.':'Used for the template and live debriefs. Your choice is saved with this activity.';}
  catch(error){if(form.isConnected){picker.innerHTML=`<option value="${e(previous||'')}">${previous?e(modelName(previous)):'Use workspace default'}</option>`;help.textContent='Model list unavailable. You can use '+(previous?'your selected model':'the workspace default')+' or tap ↻ to retry.';}}
  finally{if(form.isConnected){form.dataset.modelsLoading='false';picker.disabled=false;submit.disabled=form.dataset.voiceBusy==='true';reload.disabled=false;}}
}
function templateBusy(form,busy,message='') {const fieldset=$('fieldset',form);if(fieldset)fieldset.disabled=busy;form.setAttribute('aria-busy',String(busy));$('.template-status',form).textContent=message;if(busy)$('.template-error',form).textContent='';}
async function buildTemplate(form,values) {
  if(form.getAttribute('aria-busy')==='true'||form.dataset.voiceBusy==='true')return;
  templateBusy(form,true,'AI is building your student slides… This may take a moment.');
  try {
    const result=await api('generate_template',{description:values.description,title:values.title,workMode:values.workMode,focus:values.focus,model:values.model});
    if(!form.isConnected)return;
    if(values.prompt?.trim())result.template.debrief_prompt=values.prompt.trim();
    activityDraft={settings:{...values,model:result.model},template:result.template,model:result.model};
    modal(templateReviewForm(result.template,values,result.model));
  } catch(error) {if(form.isConnected)$('.template-error',form).textContent=error.message;}
  finally {if(form.isConnected)templateBusy(form,false);}
}
function debriefSettings(){const s=state.data.session;modal(`<div class="row spread"><h2 id="modal-title">Shape your debrief.</h2><button class="quiet icon" data-action="close-modal">×</button></div><p>Tell the AI what kind of discussion you want to lead. These instructions stay in your instructor workspace.</p><form id="debrief-settings"><div class="field"><label>Focus<select name="focus">${options(s.focus)}</select></label></div><div class="field"><label>Number of slides<input name="slideCount" type="number" min="1" max="6" value="${s.slide_count}" required></label></div><div class="field"><label>Your direction<textarea name="prompt" rows="7" maxlength="4000">${e(s.debrief_prompt)}</textarea></label></div><div class="modal-footer"><button type="button" data-action="close-modal">Cancel</button><button type="submit" class="primary">Save direction</button></div></form>`);}
function share(){modal(`<div class="row spread"><h2 id="modal-title">Invite your class.</h2><button class="quiet icon" data-action="close-modal">×</button></div>${!state.demo?`<div class="invite-preview">${qrSvg(joinLink(state.data.session.class_code))}</div>`+classInvitation(state.data.session):''}<details class="direct-links"><summary>Direct deck links & access recovery</summary><p>Send each link to its group or individual. Anyone with a group’s link can view its slides and write immediately unless you pause or end the activity. They cannot see your debrief. Choose one recorder per text box to avoid conflicting edits.</p>${state.data.groups.map(g=>`<div class="share-row"><div><strong>${e(g.name)}</strong><small>${state.data.slides.filter(s=>s.group_id===g.id).length} slide(s)</small></div><div class="row"><button data-action="copy-group" data-id="${e(g.id)}">Copy link</button><button class="quiet" data-action="rotate-group" data-id="${e(g.id)}" title="Revoke the old link and create a new one">Replace link</button></div></div>`).join('')}</details><p>Let students know their slide text is sent to OpenAI to help prepare your debrief. Contributor names are optional and appear beside examples in projected debriefs. Use only names people agree to display; omit sensitive information.</p><div class="modal-footer"><button class="primary" data-action="close-modal">Done</button></div>`);}
function groupLink(g){return location.origin+location.pathname+'#group='+g.join_token;}
async function generate(force=true){if(state.aiBusy)return;state.aiBusy=true;$('#right').innerHTML=debriefPanel();try{await flushAll();const r=await api('debrief',{sessionId:state.sessionId,force});if(r.skipped&&force)toast(r.skipped);await refresh();}catch(error){toast(error.message);}finally{state.aiBusy=false;if($('#right'))$('#right').innerHTML=debriefPanel();}}

function draftFor(id,kind){if(!state.drafts.has(id)){const original=kind==='title'?state.data.slides.find(s=>s.id===id):state.data.blocks.find(b=>b.id===id);const shown=kind==='title'?$(`[data-field="title"][data-id="${id}"]`):$(`[data-block="${id}"]`);const rendered=Number(shown?.dataset.revision);state.drafts.set(id,{kind,revision:shown&&Number.isInteger(rendered)?rendered:original.revision,values:{},seq:0,timer:null});}return state.drafts.get(id);}
function queueEdit(id,field,value){const d=draftFor(id,field==='title'?'title':'block');d.values[field]=value;d.seq++;clearTimeout(d.timer);d.timer=setTimeout(()=>saveDraft(id),650);if($('#editor-status'))$('#editor-status').textContent='Saving…';}
async function saveDraft(id){const d=state.drafts.get(id);if(!d||state.saving.has(id)||state.conflicts.has(id))return;if(state.student&&!editable()){d.waitingForReopen=true;updateStudentState();return;}state.saving.add(id);const seq=d.seq;try{const r=await api(d.kind==='title'?'save_slide':'save_block',{id,revision:d.revision,...d.values});const item=r.block||r.slide;const list=d.kind==='title'?state.data.slides:state.data.blocks;const i=list.findIndex(x=>x.id===id);if(i>=0)list[i]=item;d.revision=item.revision;const shown=d.kind==='title'?$(`[data-field="title"][data-id="${id}"]`):$(`[data-block="${id}"]`);if(shown)shown.dataset.revision=String(item.revision);if(d.seq===seq){state.drafts.delete(id);}else{d.timer=setTimeout(()=>saveDraft(id),0);}}catch(error){if(error.status===409){state.conflicts.set(id,d);toast('An edit overlaps with a teammate’s. Your draft is kept; review the conflict.');}else if(error.status===403&&state.student){d.waitingForReopen=true;state.data.session.status='paused';}else{if(!error.status||error.status>=500)state.connectionLost=true;toast('Not saved: '+error.message);d.timer=setTimeout(()=>saveDraft(id),5000);}}finally{state.saving.delete(id);if($('#editor-status'))$('#editor-status').textContent=saveStatus();paintConflictBanner();updateClock();updateStudentState();}}
async function flushAll(){for(const [id,d] of state.drafts){clearTimeout(d.timer);await saveDraft(id);}for(let i=0;i<50&&state.saving.size;i++)await new Promise(r=>setTimeout(r,100));if(state.drafts.size||state.conflicts.size)throw new Error('Please finish saving or resolve the conflicting edit first.');}
function conflictField(d){return d.kind==='title'?'title':['content','label','contributor'].find(k=>k in d.values)||'content';}
async function conflict(id){const d=state.conflicts.get(id);const field=conflictField(d);state.data=await api('get',{sessionId:state.sessionId});const current=(d.kind==='title'?state.data.slides:state.data.blocks).find(x=>x.id===id);modal(`<h2 id="modal-title">Keep both people’s thinking.</h2><p>Another editor saved this box while you were working. Compare the versions below before choosing.</p><label>Currently saved</label><div class="conflict"><p>${e(current?.[field]||'')}</p></div><label>Your unsaved draft</label><textarea id="merged-draft" rows="6">${e(d.values[field]??current?.[field]??'')}</textarea><div class="modal-footer"><button data-action="discard-draft" data-id="${e(id)}">Use saved version</button><button class="primary" data-action="keep-draft" data-id="${e(id)}">Save my merged version</button></div>`);}
async function format(field,value){if(!state.focusBlock){toast('Click a text box first, then choose its formatting.');return;}const b=state.data.blocks.find(x=>x.id===state.focusBlock);const d=state.drafts.get(b.id);const s={...b.style,...d?.values.style};if(field==='bold'||field==='italic')s[field]=!s[field];else if(field==='align')s.align=s.align==='center'?'left':'center';else s[field]=value;queueEdit(b.id,'style',s);const node=$(`[data-field="content"][data-id="${b.id}"]`);if(node){node.style.fontWeight=s.bold?'700':'400';node.style.fontStyle=s.italic?'italic':'normal';node.style.textAlign=s.align||'left';if(s.size)node.style.fontSize=s.size+'px';if(s.color)node.style.color=s.color;}}

document.addEventListener('input',event=>{const node=event.target.closest('[data-field]');if(!node)return;const value=node.dataset.field==='content'?node.innerText:node.value;if(value.length>(node.dataset.field==='content'?6000:node.dataset.field==='contributor'?120:160)){toast('This text box is too long. Please shorten it before saving.');return;}queueEdit(node.dataset.id,node.dataset.field,value);});
document.addEventListener('focusin',event=>{const node=event.target.closest('[data-block]');if(node){state.focusBlock=node.dataset.block;const b=state.data.blocks.find(x=>x.id===state.focusBlock);if($('#font-size'))$('#font-size').value=String(b?.style?.size||16);}});
document.addEventListener('paste',event=>{if(!event.target.matches('[contenteditable="true"]'))return;event.preventDefault();const value=event.clipboardData.getData('text/plain');const selection=getSelection();if(!selection.rangeCount)return;const range=selection.getRangeAt(0);range.deleteContents();const node=document.createTextNode(value);range.insertNode(node);range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range);event.target.dispatchEvent(new Event('input',{bubbles:true}));});
document.addEventListener('change',async event=>{try{if(event.target.id==='work-mode'){const individual=event.target.value==='individual';$('#workspace-count-label').textContent=individual?'Number of individual places':'Number of groups';$('#create-form [name=groups]').max=individual?'60':'20';}if(event.target.id==='font-size')await format('size',Number(event.target.value));if(event.target.id==='text-color')await format('color',event.target.value);if(event.target.id==='theme'){await flushAll();const s=selectedSlide();await api('save_slide',{id:s.id,revision:s.revision,theme:event.target.value});await refresh(true);}}catch(error){toast(error.message);}});

document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;if(form.dataset.voiceBusy==='true')return;const values=Object.fromEntries(new FormData(form));const button=$('button[type=submit]',form);if(button)button.disabled=true;
  try {
    if(form.id==='delete-activity'){try{await api('delete_session',{sessionId:values.sessionId});closeModal();await dashboard();toast('Activity deleted.');}catch(error){$('.error-text',form).textContent=error.message;}return;}
    if(form.id==='lookup-class')await lookupClass(values.code);
    if(form.id==='join-class'){
      const code=values.code.replace(/[\s-]/g,'').toUpperCase();const storageKey='sidecar-return-'+(state.joinInfo?.id||code);
      let resumeToken=localStorage.getItem(storageKey)||localStorage.getItem('sidecar-return-'+code);if(!/^[a-f0-9]{64}$/.test(resumeToken||'')){resumeToken=[...crypto.getRandomValues(new Uint8Array(32))].map(x=>x.toString(16).padStart(2,'0')).join('');localStorage.setItem(storageKey,resumeToken);}
      localStorage.setItem(storageKey,resumeToken);const result=await api('join_class',{...values,resumeToken});state.key=result.token;state.student=true;state.tester=false;state.demo=false;state.second=false;state.sessionId=null;state.selected=null;state.drafts.clear();state.conflicts.clear();history.replaceState(null,'',location.pathname+'#group='+result.token);await refresh(true);
    }
    if(form.id==='admin-form'){
      $('#admin-error').textContent='';$('#admin-message').textContent='Testing the connection and saving securely…';
      try{const result=await api('admin_save',{model:values.model,apiKey:values.apiKey.trim()});if($('#admin-api-key'))$('#admin-api-key').value='';if($('#admin-message'))$('#admin-message').textContent='Saved. The workspace default is '+result.model+'. Existing activity choices stay the same.';toast('AI settings saved securely.');}finally{if($('#admin-message')?.textContent.startsWith('Testing'))$('#admin-message').textContent='';}
    }
    if(form.id==='account-form'){const result=await api('account_'+form.dataset.mode,{email:values.email,password:values.password});state.key=result.key;state.account=true;state.sandbox=false;state.student=false;state.tester=false;state.demo=false;sessionStorage.setItem('sidecar-instructor',state.key);if(values.remember)localStorage.setItem('sidecar-instructor',state.key);else localStorage.removeItem('sidecar-instructor');if(state.sessionId)await openSession(state.sessionId);else await dashboard();return;}
    if(form.id==='login'){state.account=false;const login=await api('instructor_login',{code:values.key.trim()});state.key=login.key;state.sandbox=login.role==='sandbox';state.student=false;state.tester=false;if(state.sandbox)state.sessionId=null;await api('list');sessionStorage.setItem('sidecar-instructor',state.key);if(values.remember)localStorage.setItem('sidecar-instructor',state.key);else localStorage.removeItem('sidecar-instructor');if(state.sessionId)await openSession(state.sessionId);else await dashboard();}
    if(form.id==='create-form')await buildTemplate(form,values);
    if(form.id==='template-review'){
      if(form.getAttribute('aria-busy')==='true')return;
      const template=readTemplateReview(form),settings=activityDraft.settings;
      templateBusy(form,true,'Creating your activity and copying the template…');
      try{const data=await api('create',{workMode:settings.workMode,groups:Number(settings.groups),slideCount:Number(settings.slideCount),focus:settings.focus,model:activityDraft.model,template});if(!form.isConnected)return;state.data=data;state.sessionId=data.session.id;state.selected=data.slides[0]?.id;closeModal();setUrl();renderWorkspace();toast('Slides are open for writing. Invite the class, then start the timer and AI when ready.');}
      finally{if(form.isConnected)templateBusy(form,false);}
    }
    if(form.id==='debrief-settings'){await api('settings',{sessionId:state.sessionId,focus:values.focus,prompt:values.prompt,slideCount:Number(values.slideCount)});closeModal();await refresh();toast('Debrief direction saved.');}
    if(form.id==='start-form'){await api('settings',{sessionId:state.sessionId,status:'live',minutes:Number(values.minutes)});closeModal();await refresh(true);toast('Student editing is open.');}
    if(form.id==='activity-settings'){await api('settings',{sessionId:state.sessionId,title:values.title,instructions:values.instructions});closeModal();await refresh(true);}
  }catch(error){if(form.id==='account-form')$('#account-error').textContent=error.message;else if(form.id==='login')$('#login-error').textContent=error.message;else if(form.id==='admin-form'&&$('#admin-error'))$('#admin-error').textContent=error.message;else if(['lookup-class','join-class'].includes(form.id)&&$('#join-error'))$('#join-error').textContent=error.message;else if(['create-form','template-review'].includes(form.id)&&form.isConnected)$('.template-error',form).textContent=error.message;else toast(error.message);}finally{if(button)button.disabled=false;}
});

document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;
  try {
    if(action==='auth-signin'||action==='auth-signup')showLogin('',action==='auth-signup',$('#instructor-email')?.value||'');
    if(action==='show-password'){const input=$('#instructor-password'),show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-label',show?'Hide password':'Show password');}
    if(action==='jump-to-slide'){$('#canvas')?.scrollIntoView({behavior:'smooth',block:'start'});if(editable())$('[data-field=content]')?.focus();}
    if(action==='toggle-writing'){await flushAll();await api('settings',{sessionId:state.sessionId,status:writingOpen()?'paused':'draft'});await refresh(true);toast(writingOpen()?'Students can write now.':'Student writing is paused.');}
    if(action==='show-source')await showSource(button.dataset.slideId,button.dataset.blockId);
    if(action==='back-debrief'&&state.projection){state.projection.source=null;paintProjection();}
    if(action==='student-tools'){state.studentTools=!state.studentTools;$('.toolbar').innerHTML=toolbar();}
    if(action==='read-task'){modal(`<div class="row spread"><h2 id="modal-title">The activity brief</h2><button class="quiet icon" data-action="close-modal" aria-label="Close">×</button></div><p class="full-task">${e(state.data.session.instructions)}</p><div class="modal-footer"><button class="primary" data-action="close-modal">Back to my slides</button></div>`);}
    if(action==='admin'){await flushAll();const settings=await api('admin_status');modal(adminForm(settings));await loadModels();}
    if(action==='load-models')await loadModels();
    if(action==='test-workspace-code'){if(!confirm('Create a new test-instructor code? Any earlier test-instructor code will stop working.'))return;button.disabled=true;try{const result=await api('test_workspace_access');const code=displayCode(result.code);modal(`<h2 id="modal-title">Test instructor access</h2><p>Share this code with your tester. They can create and run activities in the test workspace using the connected AI.</p><div class="class-code">${e(code)}</div><p>Sign in at ${e(location.origin+location.pathname)}. Expires ${new Date(result.expires_at).toLocaleString()}.</p><p>Your real activities and master AI settings stay private. Replacing or revoking this code signs the tester out.</p><div class="modal-footer"><button class="primary" data-action="close-modal">Done</button></div>`);}finally{button.disabled=false;}}
    if(action==='revoke-test-workspace'){if(!confirm('Revoke test-instructor workspace access?'))return;await api('test_workspace_access',{revoke:true});toast('Test-instructor workspace access revoked.');}
    if(action==='join'||action==='join-back'){showJoin();}
    if(action==='copy-return'){await copyText(location.href,'Your private return link');}
    if(action==='leave-class'){await flushAll();const code=state.joinCode||'';state.data=null;state.student=false;state.key='';state.sessionId=null;state.selected=null;showJoin(code);if(code)await lookupClass(code);}
    if(action==='copy-class'){await copyText('Join '+state.data.session.title+'\n'+joinLink(state.data.session.class_code)+'\nClass code: '+displayCode(state.data.session.class_code),'Class invitation');}
    if(action==='present-join'){await flushAll();openJoinPresentation();}
    if(action==='join-project-close')closeJoinPresentation();
    if(action==='join-project-fullscreen'){const node=$('.join-presentation');if(node?.requestFullscreen)await node.requestFullscreen();else toast('Use your browser’s full-screen command.');}
    if(action==='join-project-copy'){const value=joinLink(state.data.session.class_code);try{await navigator.clipboard.writeText(value);toast('Student join link copied.');}catch{const input=$('#join-project-link');input.hidden=false;input.value=value;input.focus();input.select();toast('Copy the selected student link.');}}
    if(action==='toggle-join'){await api('join_settings',{sessionId:state.sessionId,enabled:!state.data.session.join_enabled});await refresh();share();}
    if(action==='rotate-class'){if(!confirm('Replace the class code? Existing deck links will still work.'))return;await api('join_settings',{sessionId:state.sessionId,rotate:true});await refresh();share();}
    if(action==='demo'){state.demo=true;state.student=false;state.tester=false;state.data=makeDemo();state.sessionId='demo';state.selected=state.data.slides[0].id;setUrl();renderWorkspace();}
    if(action==='exit-demo'){state.demo=false;state.data=null;state.sessionId=null;$('#app').className='';setUrl();state.key?await dashboard():showLogin();}
    if(action==='logout'){if(state.account){try{await api('account_logout');}catch(error){if(error.status!==401)throw error;}}state.account=false;state.tester=false;state.sandbox=false;sessionStorage.removeItem('sidecar-instructor');localStorage.removeItem('sidecar-instructor');state.key='';state.data=null;state.sessionId=null;setUrl();showLogin();}
    if(action==='home'){await flushAll();if(state.demo){toast('Leave the sample classroom to create your own activity.');return;}await dashboard();}
    if(action==='reload-activity-models')await loadActivityModels();
    if(action==='create'){activityDraft=null;setupForm();}
    if(action==='template-back'&&activityDraft)setupForm(activityDraft.settings);
    if(action==='template-regenerate'&&activityDraft)await buildTemplate($('#template-review'),activityDraft.settings);
    if(action==='open-session')await openSession(id);
    if(action==='close-modal')closeModal();
    if(action==='select-slide'||action==='source'){await flushAll();state.selected=id;if(state.second){state.second=false;setUrl();}renderWorkspace();}
    if(action==='share')share();
    if(action==='copy-group'){if(state.demo){toast('Demo links are disabled. Open your connected workspace to invite students.');return;}const link=groupLink(state.data.groups.find(g=>g.id===id));try{await navigator.clipboard.writeText(link);toast('Group link copied.');}catch{modal(`<h2 id="modal-title">Copy this group link</h2><p>Copy the link below and send it to the group.</p><input readonly value="${e(link)}" aria-label="Group link"><div class="modal-footer"><button data-action="close-modal">Done</button></div>`);}}
    if(action==='rotate-group'){if(!confirm('Replace this group’s link? Its old link will stop working.'))return;await api('rotate_group',{id});await refresh();share();toast('New group link created. Copy and share it again.');}
    if(action==='add-slide'||action==='duplicate'){await flushAll();const s=selectedSlide();const r=await api('add_slide',{groupId:s.group_id,duplicateId:action==='duplicate'?s.id:undefined,title:action==='duplicate'?s.title+' (copy)':'Our next idea'});state.selected=r.id;await refresh(true);}
    if(action==='add-block'){await flushAll();await api('add_block',{slideId:state.selected});await refresh(true);}
    if(action==='delete-slide'){if(!confirm('Delete this slide? This cannot be undone.'))return;await flushAll();await api('delete_slide',{id:state.selected});state.selected=null;await refresh(true);}
    if(action==='delete-block'){if(!confirm('Delete this text box?'))return;await flushAll();await api('delete_block',{id});await refresh(true);}
    if(action==='format')await format(button.dataset.format);
    if(action==='debrief-settings')debriefSettings();
    if(action==='generate')await generate();
    if(action==='auto'){await api('settings',{sessionId:state.sessionId,auto:!state.data.session.auto_debrief});await refresh();}
    if(action==='debrief-page')state.debriefIndex=Number(button.dataset.index);
    if(action==='debrief-next')state.debriefIndex=(state.debriefIndex+1)%Math.max(1,state.data.session.debrief?.slides.length||1);
    if(action==='debrief-prev')state.debriefIndex=(state.debriefIndex-1+(state.data.session.debrief?.slides.length||1))%Math.max(1,state.data.session.debrief?.slides.length||1);
    if(action.startsWith('debrief-')&&action!=='debrief-settings')$('#right').innerHTML=debriefPanel();
    if(action==='popout'){const url=location.origin+location.pathname+'#'+(state.demo?'demo=1':state.tester?'test='+state.key:'session='+state.sessionId)+'&view=debrief';window.open(url,'sidecar-debrief','popup,width=1100,height=850');}
    if(action==='timer'){await flushAll();const s=state.data.session;if(s.status==='live'&&s.ends_at&&new Date(s.ends_at)>new Date()){await api('settings',{sessionId:state.sessionId,status:'paused'});await refresh(true);}else modal(`<h2 id="modal-title">Give the room time to think.</h2><p>${writingOpen()?'Students can already write.':'Starting reopens student writing.'} Start the timer to begin automatic AI debriefs. When time runs out, writing stays open until you pause or end the activity.</p><form id="start-form"><div class="field"><label>Minutes<input name="minutes" type="number" min="1" max="${state.tester||state.sandbox?30:120}" value="8" required></label></div><div class="modal-footer"><button type="button" data-action="close-modal">Cancel</button><button class="primary" type="submit">Start timer & AI</button></div></form>`);}
    if(action==='activity-settings'){const s=state.data.session;modal(`<div class="row spread"><h2 id="modal-title">Activity settings</h2><button class="quiet icon" data-action="close-modal">×</button></div><form id="activity-settings"><div class="field"><label>Title<input name="title" maxlength="160" value="${e(s.title)}" required></label></div><div class="field"><label>Student instructions<textarea name="instructions" maxlength="6000" rows="6">${e(s.instructions)}</textarea></label></div><div class="row spread"><button type="button" data-action="end-activity">End activity</button>${!state.tester?'<button type="button" class="quiet danger" data-action="delete-session">Delete activity</button>':''}</div>${s.is_test&&!state.tester&&!state.sandbox?'<p><button type="button" data-action="invite-tester">Create / replace tester link</button> <button type="button" data-action="revoke-tester">Revoke tester link</button></p>':''}<div class="modal-footer"><button class="primary" type="submit">Save changes</button></div></form>`);}
    if(action==='end-activity'){await flushAll();await api('settings',{sessionId:state.sessionId,status:'ended'});closeModal();await refresh(true);}
    if(action==='delete-session'){const sessionId=id||state.sessionId,title=button.dataset.title||state.data?.session.title;modal(`<h2 id="modal-title">Delete this activity?</h2><p><strong>${e(title)}</strong></p><p>This permanently removes its student slides and debrief history. Its class code and shared links will stop working. This cannot be undone.</p><form id="delete-activity"><input type="hidden" name="sessionId" value="${e(sessionId)}"><p class="error-text" role="alert"></p><div class="modal-footer"><button type="button" data-action="close-modal">Keep activity</button><button type="submit" class="danger">Delete activity</button></div></form>`);}
    if(action==='history'){const {history}=await api('history',{sessionId:state.sessionId});state.history=history;modal(`<div class="row spread"><h2 id="modal-title">Debrief history</h2><button class="quiet icon" data-action="close-modal">×</button></div><p>Earlier readings of the room. Opening one here does not replace the current live debrief.</p>${history.length?history.map((h,i)=>`<div class="share-row"><div>${new Date(h.created_at).toLocaleString()}<small>${h.content.slides.length} slides</small></div><button data-action="history-open" data-index="${i}">View</button></div>`).join(''):'<p>No debriefs generated yet.</p>'}`);}
    if(action==='history-open'){const h=state.history[Number(button.dataset.index)];modal(`<div class="row spread"><h2 id="modal-title">Saved debrief</h2><button class="quiet icon" data-action="close-modal">×</button></div>${h.content.slides.map(s=>`<h3>${e(s.title)}</h3><p>${e(s.takeaway)}</p><ul>${s.bullets.map(b=>`<li>${e(b)}</li>`).join('')}</ul><strong>${e(s.question)}</strong>`).join('<hr>')}`);}
    if(action==='resolve-conflict')await conflict(id);
    if(action==='discard-draft'){state.drafts.delete(id);state.conflicts.delete(id);closeModal();renderWorkspace();}
    if(action==='keep-draft'){const d=state.conflicts.get(id);const current=(d.kind==='title'?state.data.slides:state.data.blocks).find(x=>x.id===id);d.revision=current.revision;const field=conflictField(d);d.values[field]=$('#merged-draft').value;state.conflicts.delete(id);closeModal();await saveDraft(id);renderWorkspace();}
    if(action==='project-debrief'){openProjection();}
    if(action==='projection-next')moveProjection(1);
    if(action==='projection-prev')moveProjection(-1);
    if(action==='projection-close')closeProjection();
    if(action==='projection-latest'){openProjection();}
    if(action==='projection-fullscreen'){const node=$('.projection-view');if(node.requestFullscreen)await node.requestFullscreen();else toast('Use your browser’s full-screen command.');}
    if(action==='invite-tester'){const r=await api('tester_access',{sessionId:state.sessionId});await navigator.clipboard.writeText(location.origin+location.pathname+'#test='+r.token);toast('Tester link copied. It expires in 7 days; any older tester link is revoked.');}
    if(action==='revoke-tester'){await api('tester_access',{sessionId:state.sessionId,revoke:true});toast('Tester link revoked.');}
    if(action==='present'){await flushAll();openGroupPresentation();}
    if(action==='close-present')closeGroupPresentation();
    if(action==='present-fullscreen'){await $('.present-view')?.requestFullscreen?.();}
    if(action==='present-next'){state.present=(state.present+1)%state.presentPages.length;renderPresentation();}
    if(action==='present-prev'){state.present=(state.present-1+state.presentPages.length)%state.presentPages.length;renderPresentation();}
    if(action==='export'){await flushAll();const d=structuredClone(state.data);delete d.session.class_code;delete d.session.legacy_class_code;d.groups=d.groups.map(({join_token,token_hash,...g})=>g);download(JSON.stringify(d,null,2),'sidecar-activity.json','application/json');toast('Activity and private debrief exported. Keep this file for yourself.');}
  }catch(error){toast(error.message);}
});
function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function openGroupPresentation(){const selected=selectedSlide();state.presentPages=state.data.slides.flatMap(slide=>groupPages(slide,state.data.blocks.filter(b=>b.slide_id===slide.id),state.data.groups.find(g=>g.id===slide.group_id),measureProjection));state.present=Math.max(0,state.presentPages.findIndex(p=>p.slide.id===selected.id));renderPresentation();$('#app').inert=true;$('#modal-root').inert=true;document.body.classList.add('projecting');$('[data-action="close-present"]')?.focus();}
function closeGroupPresentation(){if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{});$('.present-view')?.remove();state.present=null;$('#app').inert=false;$('#modal-root').inert=false;document.body.classList.remove('projecting');$('[data-action="present"]')?.focus();}
function renderPresentation(){let div=$('.present-view');if(!div){div=document.createElement('div');div.className='present-view';div.setAttribute('role','dialog');div.setAttribute('aria-label','Student slide presentation');document.body.append(div);}div.innerHTML=`<div class="projection-stage">${renderGroupPage(state.presentPages[state.present])}</div><div class="present-controls"><button data-action="close-present">← Back to editing</button><button data-action="present-prev" aria-label="Previous response">←</button><span>${state.present+1} / ${state.presentPages.length}</span><button data-action="present-next" aria-label="Next response">→</button><button data-action="present-fullscreen">Full screen</button></div>`;sizeProjection();}
document.addEventListener('keydown',event=>{
  if(state.joinProjection){if(event.key==='Escape'){closeJoinPresentation();return;}if(event.key==='Tab'){const nodes=[...$('.join-presentation').querySelectorAll('a,button,input:not([hidden])')];if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0]?.focus();}}return;}
  if(event.key==='Escape'&&state.projection){if(state.projection.source){state.projection.source=null;paintProjection();}else closeProjection();return;}
  if(state.projection&&!event.target.matches('input,textarea')){if(['ArrowRight','ArrowLeft',' '].includes(event.key)&&!(event.key===' '&&event.target.closest('button'))){event.preventDefault();moveProjection(event.key==='ArrowLeft'?-1:1);}return;}
  if(event.key==='Escape'){if($('.present-view')){closeGroupPresentation();}else closeModal();}
  if(state.present!==null&&!event.target.matches('input,textarea')){if(event.key==='ArrowRight'){state.present=(state.present+1)%state.presentPages.length;renderPresentation();}if(event.key==='ArrowLeft'){state.present=(state.present-1+state.presentPages.length)%state.presentPages.length;renderPresentation();}}
  if(event.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0]?.focus();}}
});
addEventListener('hashchange',async()=>{const target=location.hash,params=new URLSearchParams(target.slice(1));if(!params.has('join'))return;try{if(state.data)await flushAll();if(location.hash!==target)return;if(state.joinProjection)closeJoinPresentation();if(state.projection)closeProjection();closeModal();$('.present-view')?.remove();state.present=null;const code=params.get('code')||'';showJoin(code);if(code)await lookupClass(code);}catch(error){if(state.student)history.replaceState(null,'',location.pathname+'#group='+state.key);else setUrl();toast(error.message);}});
addEventListener('beforeunload',event=>{if(state.drafts.size||state.saving.size){event.preventDefault();event.returnValue='';}});
setInterval(()=>{updateClock();updateStudentState();if($('#debrief-live-line'))$('#debrief-live-line').textContent=debriefStatus();if(!document.hidden&&state.data&&!state.demo&&!state.polling)refresh();},3000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.data&&!state.demo&&!state.polling)refresh();});
setInterval(()=>{if(!state.data||state.student||state.demo||config.schedulerEnabled)return;const s=state.data.session;if(s.status==='live'&&s.auto_debrief&&new Date(s.ends_at)>new Date()&&Date.now()-state.lastAuto>=60000){state.lastAuto=Date.now();generate(false);}},5000);
if(fragment.has('join')){const code=fragment.get('code')||'';showJoin(code);if(code)lookupClass(code);}else if(state.demo){state.data=makeDemo();state.sessionId='demo';state.selected=state.data.slides[0].id;renderWorkspace();}else if(state.student||state.tester)refresh(true);else if(state.key&&state.sessionId)openSession(state.sessionId);else if(state.key)dashboard();else showLogin();

function debriefStatus(){
  const s=state.data?.session;if(!s)return '';
  if(state.demo)return 'Sample debrief · try Present debrief';
  if(state.aiBusy||s.debrief_lock_until&&new Date(s.debrief_lock_until)>new Date())return 'Reading the latest group work…';
  if(!s.auto_debrief)return 'Automatic updates are paused';
  if(s.status!=='live'||!s.ends_at||new Date(s.ends_at)<=new Date())return 'Start timer & AI to enable minute-by-minute updates';
  const seconds=60-new Date().getSeconds();
  return `Next check in ${seconds}s · unchanged work keeps this draft`;
}
function openProjection(){
  if(!state.data.session.debrief?.slides?.length){toast('Generate a debrief before presenting.');return;}
  const deck=structuredClone(state.data.session.debrief),pages=debriefPages(deck,state.data,measureProjection);state.projection={deck,pages,index:Math.max(0,pages.findIndex(p=>p.logical===state.debriefIndex)),generatedAt:state.data.session.debrief_at,source:null};
  $('.projection-view')?.remove();const node=document.createElement('div');node.className='projection-view';node.setAttribute('role','dialog');node.setAttribute('aria-label','Class debrief presentation');
  node.innerHTML='<div class="projection-stage"></div><nav class="projection-controls"><button data-action="back-debrief" hidden>← Back to debrief</button><button data-action="projection-prev" aria-label="Previous slide">←</button><span id="projection-position"></span><button data-action="projection-next" aria-label="Next slide">→</button><button data-action="projection-fullscreen">Full screen</button><button data-action="projection-latest" id="projection-update" hidden>New draft ready · Load latest</button><button data-action="projection-close">← Back to workspace</button></nav>';
  document.body.append(node);document.body.classList.add('projecting');$('#app').inert=true;$('#modal-root').inert=true;paintProjection();$('.projection-controls button')?.focus();
}
async function showSource(slideId,blockId){
 await flushAll();if(!state.projection)openProjection();if(!state.projection)return;const projection=state.projection;const fresh=await api('get',{sessionId:state.sessionId});if(state.projection!==projection)return;state.data=fresh;const slide=fresh.slides.find(s=>s.id===slideId);if(!slide){toast('This source slide is no longer available.');return;}
 const pages=groupPages(structuredClone(slide),structuredClone(state.data.blocks.filter(b=>b.slide_id===slideId)),structuredClone(state.data.groups.find(g=>g.id===slide.group_id)),measureProjection);
 state.projection.source={pages,index:Math.max(0,pages.findIndex(p=>p.block.id===blockId))};paintProjection();$('[data-action="back-debrief"]')?.focus();
}
function paintProjection(){const p=state.projection;if(!p)return;const source=p.source,entry=p.pages[p.index];$('.projection-stage').innerHTML=source?renderGroupPage(source.pages[source.index]):renderDebriefSlide(entry.slide,{index:entry.logical,total:p.deck.slides.length,title:state.data.session.title,evidenceAt:p.deck.evidence_at,data:state.data});$('#projection-position').textContent=source?`Student response ${source.index+1} / ${source.pages.length}`:`Debrief ${entry.logical+1} / ${p.deck.slides.length} · View ${p.index+1} / ${p.pages.length}`;$('[data-action="back-debrief"]').hidden=!source;sizeProjection();updateProjectionNotice();}
function sizeProjection(){const scale=Math.max(.1,Math.min(((globalThis.innerWidth||1280)-24)/1280,((globalThis.innerHeight||800)-84)/720));document.querySelectorAll('.projection-stage:not(.projection-measure)').forEach(stage=>stage.style.setProperty('--projection-scale',scale));}
function updateProjectionNotice(){const button=$('#projection-update');if(button)button.hidden=Boolean(state.projection.source)||state.projection.generatedAt===state.data.session.debrief_at;}
function moveProjection(direction){const p=state.projection;if(!p)return;if(p.source)p.source.index=(p.source.index+direction+p.source.pages.length)%p.source.pages.length;else p.index=(p.index+direction+p.pages.length)%p.pages.length;paintProjection();}
function closeProjection(){if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{});$('.projection-view')?.remove();document.body.classList.remove('projecting');$('#app').inert=false;$('#modal-root').inert=false;state.projection=null;$('[data-action="project-debrief"]')?.focus();}
addEventListener('resize',sizeProjection);

document.addEventListener('fullscreenchange',sizeProjection);

function showJoin(code='',classroom=null){state.viewEpoch++;state.data=null;state.demo=false;state.student=false;state.tester=false;state.sandbox=false;state.second=false;state.key='';state.sessionId=null;state.joinInfo=classroom;state.joinCode=code;history.replaceState(null,'',location.pathname+'#join'+(code?'&code='+encodeURIComponent(code.replace(/[\s-]/g,'').toUpperCase()):''));$('#app').className='';$('#app').innerHTML=joinForm(code,classroom);if(!code&&globalThis.innerWidth>600)$('#class-code')?.focus();}
async function lookupClass(code){const epoch=state.viewEpoch,button=$('#lookup-class button[type=submit]');if(button){button.disabled=true;button.textContent='Finding your class…';}try{const result=await api('lookup_class',{code});if(epoch===state.viewEpoch)showJoin(code,result);}catch(error){if(epoch===state.viewEpoch&&$('#join-error'))$('#join-error').textContent=error.message;}finally{if(button){button.disabled=false;button.textContent='Find class →';}}}
function openJoinPresentation(){if(state.student||state.demo||!state.data)return;closeModal();if(state.projection)closeProjection();const node=document.createElement('section');node.className='join-presentation';node.setAttribute('role','dialog');node.setAttribute('aria-modal','true');node.setAttribute('aria-labelledby','join-project-title');node.innerHTML='<div class="join-project-stage"></div><nav class="join-project-controls" aria-label="Join presentation controls"><input id="join-project-link" readonly hidden aria-label="Student join link"><button data-action="join-project-copy">Copy join link</button><button data-action="join-project-fullscreen">Full screen</button><button data-action="join-project-close">Back to instructor ×</button></nav>';document.body.append(node);state.joinProjection={signature:''};$('#app').inert=true;$('#modal-root').inert=true;document.body.classList.add('projecting');paintJoinPresentation();$('[data-action="join-project-close"]')?.focus();}
function paintJoinPresentation(){if(!state.joinProjection)return;const s=state.data.session,signature=JSON.stringify([s.class_code,s.join_enabled,s.status,s.title,s.work_mode]);if(signature===state.joinProjection.signature)return;$('.join-project-stage').innerHTML=joinPresentation(s);state.joinProjection.signature=signature;}
function closeJoinPresentation(){if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{});$('.join-presentation')?.remove();state.joinProjection=null;$('#app').inert=false;$('#modal-root').inert=false;document.body.classList.remove('projecting');$('[data-action="share"]')?.focus();}
async function loadModels(){const error=$('#admin-error'),message=$('#admin-message'),button=$('[data-action="load-models"]');if(!button)return;button.disabled=true;error.textContent='';message.textContent='Loading models available to this key…';try{const current=$('#admin-model').value;const result=await api('admin_models',{apiKey:$('#admin-api-key').value.trim()});if(!result.models.length)throw new Error('No compatible text models were found for this key.');$('#admin-model').innerHTML=result.models.map(id=>`<option value="${e(id)}" ${id===current?'selected':''}>${e(id)}</option>`).join('');message.textContent='Choose a model, then test and save. Your current settings have not changed.';}catch(err){error.textContent=err.message;message.textContent='';}finally{button.disabled=false;}}
async function copyText(value,title){try{await navigator.clipboard.writeText(value);toast(title+' copied.');}catch{modal(`<h2 id="modal-title">${e(title)}</h2><p>Copy the text below.</p><textarea rows="4" readonly>${e(value)}</textarea><div class="modal-footer"><button data-action="close-modal">Done</button></div>`);}}
function syncOtherBlocks(){for(const block of state.data.blocks.filter(b=>b.slide_id===state.selected)){const node=$(`[data-block="${block.id}"]`);if(node&&!node.contains(document.activeElement)&&!state.drafts.has(block.id)&&!state.conflicts.has(block.id))node.outerHTML=blockHtml(block,!editable());}}

function conflictsHtml(){return state.conflicts.size?`<div id="conflict-alert" role="status">${[...state.conflicts.keys()].map(id=>`<div class="conflict"><div><strong>Two edits, one text box.</strong><p>Your draft is kept. Compare it with the saved version before continuing.</p></div><button data-action="resolve-conflict" data-id="${e(id)}">Compare edits</button></div>`).join('')}</div>`:'';}
function paintConflictBanner(){const canvas=$('#canvas');if(!canvas)return;$('#conflict-alert')?.remove();if(state.conflicts.size)canvas.insertAdjacentHTML('afterbegin',conflictsHtml());}
function groupProgress(groupId){const ids=new Set(state.data.slides.filter(s=>s.group_id===groupId).map(s=>s.id));const blocks=state.data.blocks.filter(b=>ids.has(b.slide_id));const count=blocks.filter(b=>b.content.trim()).length;return count?`${count} of ${blocks.length} boxes with writing`:'No writing yet';}
function roomSummary(){const written=state.data.groups.filter(g=>groupProgress(g.id)!=='No writing yet').length;return `<div class="room-summary"><strong>${written}<span> / ${state.data.groups.length}</span></strong><span>${state.data.session.work_mode==='individual'?'students':'groups'} with writing</span><div class="room-progress"><i style="width:${written/state.data.groups.length*100}%"></i></div><small>Saved work · updates live</small></div>`;}
function studentTask(){const s=state.data.session,brief=s.instructions||'Add your response to the prompts below.';return `<section class="student-task"><div class="task-heading"><span class="eyebrow">Your task</span><button class="quiet" data-action="read-task">Read full brief ↗</button></div><p>${e(brief.length>150?brief.slice(0,150).replace(/\s+\S*$/,'')+'…':brief)}</p><div class="student-guidance">${s.work_mode==='individual'?'Write your own response. Your instructor can see your saved work.':'Use separate boxes to write together, or choose one recorder.'}</div><div id="student-state" role="status"></div><button class="quiet jump-to-slide" data-action="jump-to-slide">✍️ Write my response ↓</button></section>`;}
function updateStudentState(){if(!state.student||!state.data||!$('#workspace'))return;const open=editable();if(state.lastEditing!==open){state.lastEditing=open;const toolbarNode=$('.toolbar');if(toolbarNode)toolbarNode.innerHTML=toolbar();$('#canvas')?.querySelectorAll('[data-field]').forEach(node=>{if(node.dataset.field==='content')node.setAttribute('contenteditable',String(open));else node.readOnly=!open;});$('#canvas')?.querySelectorAll('.block-delete').forEach(node=>node.hidden=!open);}
 const status=$('#student-state'),s=state.data.session;
 const task=$('.student-task>p'),brief=s.instructions||'Add your response to the prompts below.';if(task)task.textContent=brief.length>150?brief.slice(0,150).replace(/\s+\S*$/,'')+'…':brief;
 if(status){const waiting=state.drafts.size&&!open;status.className='student-state '+(open?'writing':'waiting');status.innerHTML=`<span class="dot"></span><strong>${state.connectionLost?'Connection interrupted':waiting?'Draft kept in this tab':open?'Open for writing':'Writing is paused'}</strong><span>${state.connectionLost?'Keep this tab open. Your edits will retry when the connection returns.':waiting?'Your draft can save when the activity reopens.':open?'Tap a response box to write. Your changes save automatically.':'Your instructor can reopen writing. Your saved ideas are ready for discussion.'}</span>`;}
 if(open)for(const [id,d] of state.drafts){if(d.waitingForReopen){d.waitingForReopen=false;saveDraft(id);}}
 if($('#editor-status'))$('#editor-status').textContent=saveStatus();
}
